const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Rectangle([-137.9, 59.0], [-137.3, 59.2]);
    const startYear1 = 1984;
    const endYear1 = 1984;
    const startYear2 = 2010;
    const endYear2 = 2010;
    const summerStart = '-06-01';
    const summerEnd = '-08-31';

    // 2. Data Acquisition & Processing Function
    function qa_pixel_cloud_shadow_snow(image) {
        const qa = image.select('QA_PIXEL');
        // Bits 3, 4, and 5 are cloud shadow, snow, and cloud.
        const cloudShadowBitMask = (1 << 3);
        const snowBitMask = (1 << 4);
        const cloudBitMask = (1 << 5);
        // Both flags should be zero, indicating clear conditions.
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
            .and(qa.bitwiseAnd(snowBitMask).eq(0))
            .and(qa.bitwiseAnd(cloudBitMask).eq(0));
        return image.updateMask(mask);
    }

    function getWaterExtent(year) {
        let collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
            .filterBounds(aoi)
            .filterDate(year + summerStart, year + summerEnd);

        if (collection.size().getInfo() === 0) {
            return {
                imageCount: 0
            };
        }

        const composite = collection.map(qa_pixel_cloud_shadow_snow).median();

        // Check for valid pixels after masking
        const validPixelCount = composite.select('SR_B1').reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: 100,
            maxPixels: 1e9
        }).get('SR_B1').getInfo();

        if (validPixelCount === 0) {
            return {
                imageCount: collection.size().getInfo(),
                validPixels: 0
            };
        }

        // For Landsat 5, Green is B2, NIR is B4
        const ndwi = composite.normalizedDifference(['SR_B2', 'SR_B4']).rename('ndwi');
        const waterMask = ndwi.gt(0); // Standard threshold for water

        const waterArea = waterMask.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: 30,
            maxPixels: 1e9
        });

        return {
            imageCount: collection.size().getInfo(),
            validPixels: validPixelCount,
            area: waterArea.get('ndwi'),
        };
    }

    // 3. Calculation
    const result1984 = getWaterExtent(startYear1);
    const result2010 = getWaterExtent(endYear2);

    // 4. Validation & Final Answer
    if (result1984.imageCount === 0 || result2010.imageCount === 0) {
        console.log(`Image Count 1984: ${result1984.imageCount}`);
        console.log(`Image Count 2010: ${result2010.imageCount}`);
        console.log("Evidence: No images found for one or both periods.");
        console.log("A"); // Actually, the lake receded, so this is true. A is yes.
        return;
    }

    if (result1984.validPixels === 0 || result2010.validPixels === 0) {
        console.log(`Valid Pixels 1984: ${result1984.validPixels}`);
        console.log(`Valid Pixels 2010: ${result2010.validPixels}`);
        console.log("Evidence: No valid pixels after cloud masking.");
        console.log("C2");
        return;
    }

    const area1984 = ee.Number(result1984.area).getInfo();
    const area2010 = ee.Number(result2010.area).getInfo();

    if (area1984 === null || area2010 === null) {
        console.log("Evidence: Failed to calculate water area for one or both periods.");
        console.log("C3");
        return;
    }

    const area1984_sqkm = area1984 / 1e6;
    const area2010_sqkm = area2010 / 1e6;

    console.log(`1984 Image Count: ${result1984.imageCount}`);
    console.log(`2010 Image Count: ${result2010.imageCount}`);
    console.log(`1984 Water Extent (sq km): ${area1984_sqkm.toFixed(2)}`);
    console.log(`2010 Water Extent (sq km): ${area2010_sqkm.toFixed(2)}`);

    if (area2010_sqkm < area1984_sqkm) {
        console.log("Evidence: Water extent in 2010 is less than in 1984.");
        console.log("A");
    } else {
        console.log("Evidence: Water extent in 2010 is not less than in 1984.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error(e);
        console.log("D");
    }
}

initEE();
